// ================= НАСТРОЙКИ АГЕНТА =================
// Меняйте только значения справа от двоеточия. Подробно — docs/02-setup.md.
const config = {
  // О компании — агент говорит от её имени
  company: 'Название компании',
  about: 'Чем вы занимаетесь, одним предложением',
  support_hours: 'пн–пт 9:00–18:00 (Киев)',
  contact_fallback: 'support@example.com',

  // Google Таблица с листами Knowledge, Orders, Tickets, Log
  spreadsheet_id: 'ВСТАВЬТЕ_ID_ТАБЛИЦЫ',

  // Telegram-чат команды, куда приходят передачи человеку
  team_chat_id: 'ВСТАВЬТЕ_ID_ЧАТА',

  // Ключ, без которого вебхук не отвечает. Длинная случайная строка.
  agent_token: 'ЗАМЕНИТЕ_НА_ДЛИННУЮ_СЛУЧАЙНУЮ_СТРОКУ',

  // Ограничения
  max_message_chars: 2000,     // длиннее — обрезается
  rate_limit_messages: 20,     // сообщений от одного клиента...
  rate_limit_minutes: 10,      // ...за столько минут
  daily_agent_runs: 1000,      // потолок ответов модели в сутки — защита бюджета
  handoff_pause_minutes: 30,   // после передачи человеку бот молчит в этом диалоге

  // Поиск по базе знаний: доля слов вопроса, которая должна найтись в статье (0–1)
  kb_min_score: 0.3,

  // Обещания, которые агент давать не может: регулярные выражения
  forbidden: [
    '(верн(ём|ем|у)|возврат(им)?|компенсиру(ем|ю)|дадим|предостав(им|лю)|сделаем)[^.!?]{0,40}(деньг|скидк|компенсац|бесплатн|промокод)',
    'гарантиру(ю|ем)',
    '(refund|compensate|give you a discount|guarantee)',
  ],

  // Служебная метка в системной инструкции. Если она появится в ответе — ответ не уйдёт клиенту.
  canary: 'KX-91-CANARY',

  // Ключ для прогона evals: запрос с заголовком x-agent-debug, равным ему, получает в ответе
  // список вызванных инструментов. Пусто — режим выключен. Не кладите его на сайт.
  debug_token: '',
};

return [{ json: { config, input: $input.first().json } }];

