const g = $input.first().json;
const alerts = {
  handoff: '🙋 Клиент просит человека',
  forward: '💬 Новое сообщение в диалоге, переданном вам',
};
const title = alerts[g.kind];
let alert_html = '';
if (title) {
  const c = g.customer || {};
